        "Path is outside the session root",
        inputPath,
        "invalid_path",
      );
    }

    const trimmed = inputPath.trim();

    if (trimmed.length === 0)
    {
      throw new PathEscapeError(
        "Path is outside the session root",
        inputPath,
        "empty_path",
